import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { useTranslation } from '../hooks/useTranslation';
import '../styles/dialogues.css';
import '../styles/ui.css';

const Dialogues = () => {
  const { language: currentLanguage } = useLanguage();
  const t = useTranslation();

  // App state
  const [dialogues, setDialogues] = useState({});
  const [currentDialogue, setCurrentDialogue] = useState('morning_routine');
  const [currentDialogueData, setCurrentDialogueData] = useState(null);
  const [themes, setThemes] = useState([]);
  const [visibleThemes, setVisibleThemes] = useState(3);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [data, setData] = useState(null);

  // Media player state
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [lastVolume, setLastVolume] = useState(0.7);
  const [showTranslations, setShowTranslations] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showVolumePopup, setShowVolumePopup] = useState(false);

  const audioRefs = useRef([]);
  const progressIntervalRef = useRef(null);
  const phraseDurations = useRef([]);

  useEffect(() => {
    init();
  }, []);

  useEffect(() => {
    if (data && currentLanguage) {
      loadDialogue(currentDialogue, currentLanguage);
    }
  }, [currentLanguage, data]);

  const init = async () => {
    try {
      setLoading(true);
      await loadData();
      await loadDialogue('morning_routine', currentLanguage);
      setupEventListeners();
    } catch (err) {
      setError('Failed to initialize app');
      console.error('Error initializing app:', err);
    } finally {
      setLoading(false);
    }
  };

  const loadData = async () => {
    try {
      const response = await fetch('/data/data.json');
      const jsonData = await response.json();
      setData(jsonData);

      // Carregar temas do data.json com seus tópicos
      const themeList = jsonData.themes || [];
      setThemes(themeList);
    } catch (err) {
      console.error('Error loading data:', err);
      throw err;
    }
  };

  const loadDialogue = async (dialogueId, language = 'en') => {
    try {
      const txtContent = await loadDialogueTxt(dialogueId, language);
      if (txtContent) {
        const parsedDialogue = parseDialogueTxt(txtContent);

        // Ensure translations
        ensureTranslations(parsedDialogue);

        setCurrentDialogueData(parsedDialogue);
        setCurrentDialogue(dialogueId);

        // Reset player state
        stopDialogue();

        // Preload audios
        await preloadAudios(dialogueId, language);
      }
    } catch (err) {
      console.error('Error loading dialogue:', err);
      setError('Failed to load dialogue');
    }
  };

  const loadDialogueTxt = async (dialogueId, language) => {
    try {
      const response = await fetch(`/dialogues/${language}/${dialogueId}.txt`);
      if (!response.ok) {
        // Try fallback language
        const fallbackResponse = await fetch(`/dialogues/en/${dialogueId}.txt`);
        if (!fallbackResponse.ok) throw new Error('Dialogue not found');
        return await fallbackResponse.text();
      }
      return await response.text();
    } catch (err) {
      console.error('Error loading dialogue txt:', err);
      return null;
    }
  };

  const parseDialogueTxt = (content) => {
    const lines = content.split('\n').filter(line => line.trim());
    const dialogue = { title: '', phrases: [] };

    for (const line of lines) {
      if (line.startsWith('TITLE:')) {
        dialogue.title = line.replace('TITLE:', '').trim();
      } else if (line.includes(':')) {
        const colonIndex = line.indexOf(':');
        const speaker = line.substring(0, colonIndex).trim();
        const text = line.substring(colonIndex + 1).trim();

        // Check for translation in parentheses
        let translation = '';
        const translationMatch = text.match(/\(([^)]+)\)$/);
        if (translationMatch) {
          translation = translationMatch[1];
        }

        dialogue.phrases.push({
          speaker,
          text: text.replace(/\([^)]+\)$/, '').trim(),
          translation
        });
      }
    }

    return dialogue;
  };

  const ensureTranslations = (dialogue) => {
    if (!dialogue.phrases) return;

    dialogue.phrases.forEach(phrase => {
      if (!phrase.translation && data?.translations?.[currentLanguage]) {
        // Try to find translation in data
        const key = phrase.text.toLowerCase().replace(/[^a-z0-9]/g, '');
        phrase.translation = data.translations[currentLanguage][key] || '';
      }
    });
  };

  const preloadAudios = async (dialogueId, language) => {
    if (!currentDialogueData?.phrases) return;

    // Clear existing audio elements
    audioRefs.current.forEach(audio => {
      if (audio && typeof audio.pause === 'function') {
        audio.pause();
      }
    });
    audioRefs.current = [];

    const audioPromises = currentDialogueData.phrases.map((_, index) => {
      return new Promise((resolve) => {
        const audio = new Audio();
        audio.preload = 'auto';

        // Use correct audio path structure: /audio/{language}/{dialogueId}/line_{index}.mp3
        audio.src = `/audio/${language}/${dialogueId}/line_${index}.mp3`;
        audio.volume = volume;

        const handleLoad = () => {
          console.log(`Audio loaded successfully for line ${index}`);
          audio.removeEventListener('loadeddata', handleLoad);
          audio.removeEventListener('error', handleError);
          resolve(audio);
        };

        const handleError = (e) => {
          console.error(`Error loading audio for line ${index}:`, e);
          console.error(`Audio path: ${audio.src}`);

          // Fallback to English if language not found
          if (language !== 'en') {
            console.warn(`Audio ${dialogueId}/line_${index}.mp3 not found for ${language}, trying English`);
            audio.src = `/audio/en/${dialogueId}/line_${index}.mp3`;
            return; // Let it try again with English
          }

          audio.removeEventListener('loadeddata', handleLoad);
          audio.removeEventListener('error', handleError);
          resolve(null);
        };

        audio.addEventListener('loadeddata', handleLoad);
        audio.addEventListener('error', handleError);
        audio.addEventListener('canplaythrough', () => {
          console.log(`Audio can play through for line ${index}`);
        });
      });
    });

    const loadedAudios = await Promise.all(audioPromises);
    audioRefs.current = loadedAudios;

    // Calculate durations
    calculateDurations();
  };

  const calculateDurations = () => {
    const durations = audioRefs.current.map(audio => audio?.duration || 0);
    phraseDurations.current = durations;
    const total = durations.reduce((sum, duration) => sum + duration, 0);
    setTotalTime(total);
  };



  const playDialogue = () => {
    if (audioRefs.current.length === 0) return;

    setIsPlaying(true);
    playCurrentPhrase();
  };

  const pauseDialogue = () => {
    setIsPlaying(false);
    audioRefs.current.forEach(audio => audio?.pause());
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }
  };

  const stopDialogue = () => {
    setIsPlaying(false);
    setCurrentPhraseIndex(0);
    setCurrentTime(0);

    audioRefs.current.forEach(audio => {
      if (audio) {
        audio.pause();
        audio.currentTime = 0;
      }
    });

    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }

    removeAllHighlights();
  };

  const playCurrentPhrase = () => {
    if (currentPhraseIndex >= audioRefs.current.length) {
      setIsPlaying(false);
      setCurrentPhraseIndex(0);
      return;
    }

    const audio = audioRefs.current[currentPhraseIndex];
    if (audio) {
      audio.volume = isMuted ? 0 : volume;
      audio.currentTime = 0;

      const playPromise = audio.play();
      if (playPromise) {
        playPromise.catch(err => console.error('Audio play failed:', err));
      }

      audio.onended = () => {
        if (isPlaying) {
          setCurrentPhraseIndex(prev => {
            const nextIndex = prev + 1;
            if (nextIndex < audioRefs.current.length) {
              setTimeout(() => playCurrentPhrase(), 500);
            } else {
              setIsPlaying(false);
              setCurrentPhraseIndex(0);
            }
            return nextIndex;
          });
        }
      };

      startProgressTracking();
      highlightCurrentPhrase();
    }
  };

  const playPhrase = (index) => {
    if (index < 0 || index >= audioRefs.current.length) return;

    // Stop current playback
    stopDialogue();

    setCurrentPhraseIndex(index);
    setIsPlaying(true);

    const audio = audioRefs.current[index];
    if (audio) {
      audio.volume = isMuted ? 0 : volume;
      audio.currentTime = 0;
      audio.play();

      audio.onended = () => {
        setIsPlaying(false);
      };

      startProgressTracking();
      highlightCurrentPhrase();
    }
  };

  const highlightCurrentPhrase = () => {
    removeAllHighlights();
    const phraseElement = document.querySelector(`[data-phrase-index="${currentPhraseIndex}"]`);
    if (phraseElement) {
      phraseElement.classList.add('highlighted');
    }
  };

  const removeAllHighlights = () => {
    document.querySelectorAll('.message.highlighted').forEach(el => {
      el.classList.remove('highlighted');
    });
  };

  const startProgressTracking = () => {
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }

    progressIntervalRef.current = setInterval(() => {
      updateProgress();
    }, 100);
  };

  const updateProgress = () => {
    const currentAudio = audioRefs.current[currentPhraseIndex];
    if (currentAudio && !currentAudio.paused) {
      const elapsed = phraseDurations.current.slice(0, currentPhraseIndex)
        .reduce((sum, duration) => sum + duration, 0) + currentAudio.currentTime;
      setCurrentTime(elapsed);
    }
  };

  const toggleTranslations = () => {
    setShowTranslations(!showTranslations);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const toggleMute = () => {
    if (isMuted) {
      setIsMuted(false);
      setVolume(lastVolume);
      audioRefs.current.forEach(audio => {
        if (audio) audio.volume = lastVolume;
      });
    } else {
      setLastVolume(volume);
      setIsMuted(true);
      setVolume(0);
      audioRefs.current.forEach(audio => {
        if (audio) audio.volume = 0;
      });
    }
  };

  const updateVolume = (newVolume) => {
    setVolume(newVolume);
    setIsMuted(newVolume === 0);
    audioRefs.current.forEach(audio => {
      if (audio) audio.volume = newVolume;
    });

    // Save to localStorage
    localStorage.setItem('appVolume', newVolume.toString());
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleProgressBarClick = (e) => {
    const progressBar = e.currentTarget;
    const rect = progressBar.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const percentage = clickX / rect.width;
    const targetTime = percentage * totalTime;

    // Find which phrase this time corresponds to
    let accumulatedTime = 0;
    let targetPhraseIndex = 0;

    for (let i = 0; i < phraseDurations.current.length; i++) {
      if (accumulatedTime + phraseDurations.current[i] > targetTime) {
        targetPhraseIndex = i;
        break;
      }
      accumulatedTime += phraseDurations.current[i];
    }

    const offsetInPhrase = targetTime - accumulatedTime;
    setCurrentPhraseIndex(targetPhraseIndex);

    const audio = audioRefs.current[targetPhraseIndex];
    if (audio) {
      audio.currentTime = Math.max(0, Math.min(offsetInPhrase, audio.duration));
      if (isPlaying) {
        audio.play();
      }
    }
  };

  const loadMoreThemes = () => {
    setVisibleThemes(prev => Math.min(prev + 3, themes.length));
  };

  const showLessThemes = () => {
    setVisibleThemes(3);
  };

  const setupEventListeners = () => {
    // Handle fullscreen changes
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);

    // Cleanup
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
    };
  };

  // Load volume preference on mount
  useEffect(() => {
    const savedVolume = localStorage.getItem('appVolume');
    if (savedVolume !== null) {
      const vol = parseFloat(savedVolume);
      setVolume(vol);
      setIsMuted(vol === 0);
    }
  }, []);



  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>{t('loading')}</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-container">
        <p>{error}</p>
        <button onClick={init}>{t('retry')}</button>
      </div>
    );
  }

  return (
    <div className="content-below-navbar">
      <div className="page-title-container">
        <h1 className="page-title">Diálogos</h1>
      </div>

      <div className="container">
        <div className="dialogue-container">
          <h2 className="dialogue-title">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
            <span>{currentDialogueData?.title || 'Loading...'}</span>
          </h2>

          <div id="dialogue-content">
            {currentDialogueData?.phrases?.map((phrase, index) => (
              <div 
                key={index} 
                className={`message ${currentPhraseIndex === index && isPlaying ? 'highlighted' : ''}`}
                data-phrase-index={index}
                onClick={() => playPhrase(index)}
              >
                <div className="speaker">{phrase.speaker}</div>
                <div className="text">{phrase.text}</div>
                {showTranslations && phrase.translation && (
                  <div className="translation">{phrase.translation}</div>
                )}
              </div>
            ))}
          </div>

          <div className="media-player">
            <div className="player-controls">
              <button 
                className="player-btn" 
                onClick={isPlaying ? pauseDialogue : playDialogue}
                title={isPlaying ? 'Pause' : 'Play'}
              >
                <i className={`fas fa-${isPlaying ? 'pause' : 'play'}`}></i>
              </button>
              <button className="player-btn" onClick={stopDialogue} title="Stop">
                <i className="fas fa-stop"></i>
              </button>
              <button 
                className={`player-btn ${showTranslations ? 'active' : ''}`} 
                onClick={toggleTranslations}
                title="Toggle Translations"
              >
                <i className="fas fa-language"></i>
              </button>
              <button 
                className="player-btn" 
                onClick={toggleFullscreen}
                title="Toggle Fullscreen"
              >
                <i className={`fas fa-${isFullscreen ? 'compress' : 'expand'}`}></i>
              </button>
              <div className="volume-control">
                <button 
                  className="volume-btn" 
                  onClick={() => setShowVolumePopup(!showVolumePopup)}
                  title="Volume"
                >
                  <i className={`fas fa-volume-${isMuted ? 'mute' : volume > 0.5 ? 'up' : 'down'}`}></i>
                </button>
                <input 
                  type="range" 
                  id="volume-slider"
                  min="0" 
                  max="1" 
                  step="0.1" 
                  value={volume}
                  onChange={(e) => updateVolume(parseFloat(e.target.value))}
                  title="Volume Control"
                />
              </div>
            </div>
            <div className="progress-container">
              <div 
                className="progress-bar-container"
                onClick={handleProgressBarClick}
              >
                <div 
                  className="progress-bar" 
                  style={{ width: `${totalTime > 0 ? (currentTime / totalTime) * 100 : 0}%` }}
                ></div>
              </div>
              <div className="time-display">
                <span id="current-time">{formatTime(currentTime)}</span>
                <span id="total-time">{formatTime(totalTime)}</span>
              </div>
            </div>
          </div>
        </div>

        <h2 className="section-title">{t('chooseTheme')}</h2>

        <div className="theme-grid" id="theme-container">
          {themes.slice(0, visibleThemes).map((theme, index) => (
            <div 
              key={index} 
              className="theme-card"
            >
              <h3>{theme.title}</h3>
              <ul>
                {theme.topics && theme.topics.map((topic) => (
                  <li 
                    key={topic.id}
                    className={currentDialogue === topic.id ? 'active' : ''}
                    onClick={() => loadDialogue(topic.id, currentLanguage)}
                  >
                    {topic.name}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="theme-controls">
          {visibleThemes < themes.length && (
            <button className="theme-control-btn" onClick={loadMoreThemes}>
              <i className="fas fa-chevron-down"></i>
              <span>{t('loadMore')}</span>
            </button>
          )}
          {visibleThemes > 3 && (
            <button className="theme-control-btn" onClick={showLessThemes}>
              <i className="fas fa-chevron-up"></i>
              <span>{t('showLess')}</span>
            </button>
          )}
        </div>

        <div className="text-center">
          <a href="/signup" className="cta-button">{t('startLearning')}</a>
        </div>
      </div>

      {/* Volume Popup for Mobile */}
      {showVolumePopup && (
        <div className="volume-popup" onClick={() => setShowVolumePopup(false)}>
          <div className="volume-popup-content" onClick={(e) => e.stopPropagation()}>
            <div className="volume-header">
              <span>{t('volume')}</span>
              <button 
                className="volume-close-btn"
                onClick={() => setShowVolumePopup(false)}
              >
                &times;
              </button>
            </div>
            <div className="volume-slider-container">
              <input 
                type="range" 
                className="mobile-volume-slider"
                min="0" 
                max="1" 
                step="0.1" 
                value={volume}
                onChange={(e) => updateVolume(parseFloat(e.target.value))}
              />
              <div className="volume-labels">
                <span>0%</span>
                <span>50%</span>
                <span>100%</span>
              </div>
            </div>
            <div className="volume-buttons">
              <button 
                className="volume-preset-btn" 
                onClick={() => updateVolume(0.3)}
              >
                30%
              </button>
              <button 
                className="volume-preset-btn" 
                onClick={() => updateVolume(0.6)}
              >
                60%
              </button>
              <button 
                className="volume-preset-btn" 
                onClick={() => updateVolume(1)}
              >
                100%
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dialogues;
